import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../models/family.dart'; import '../../state/providers.dart'; import '../../widgets/app_scaffold.dart';
class AppearanceSettingsScreen extends ConsumerWidget{ const AppearanceSettingsScreen({super.key,required this.familyId}); final String familyId; @override Widget build(BuildContext context, WidgetRef ref){ final fam=ref.watch(familyProvider(familyId)).valueOrNull; if(fam==null)return const Scaffold(body:Center(child:CircularProgressIndicator())); Future<void> save(FamilySettings s)=>ref.read(repositoryProvider).saveFamily(fam.copyWith(settings:s)); return AppScaffold(title:'Appearance', familyId:familyId, child:ListView(padding:const EdgeInsets.all(16), children:[Text('Photo shape', style:Theme.of(context).textTheme.titleLarge), Wrap(spacing:12, children:[for(final shape in const ['circle','square','rounded-square','hexagon']) ChoiceChip(label:Text(shape), selected:fam.settings.photoShape==shape, avatar:const Icon(Icons.account_circle), onSelected:(_)=>save(fam.settings.copyWith(photoShape:shape)))]), const Divider(), Text('Gender border colors', style:Theme.of(context).textTheme.titleLarge), for(final g in const ['male','female','other']) ListTile(title:Text(g), leading:CircleAvatar(backgroundColor:_c(fam.settings.genderColors[g]!)), trailing:Wrap(children:[for(final h in const ['#2E86DE','#E84393','#8E44AD','#16A085','#E67E22','#34495E']) InkWell(onTap:(){final m=Map<String,String>.from(fam.settings.genderColors); m[g]=h; save(fam.settings.copyWith(genderColors:m));}, child:Padding(padding:const EdgeInsets.all(4), child:CircleAvatar(radius:14, backgroundColor:_c(h))))]))])); }} Color _c(String h)=>Color(int.parse(h.substring(1),radix:16)+0xFF000000);
